\section{Introduction}

\subsection{The empirical setting}
A factor-search procedure applied to a semiprime $N=pq$ sweeps candidate offsets and occasionally records a \emph{hit}. Collecting hits across a corpus of semiprimes and rescaling offsets to a common window produces a \emph{positional hit profile}: a decreasing density $T(x)$, $x\in[0,2]$, with $x=0$ the near end (small offsets, the ``wall'') and $x=2$ the far end.

The dataset re-analysed here consists of $9594$ hits from $128$ semiprimes of bit-length $96$. Its profile is well fitted by
\begin{equation}\label{eq:fit}
T(x)\;\approx\;0.0295\,(1+x)^{-1.104},
\end{equation}
with a cluster-resampling interval $b\in[0.991,1.218]$ and Akaike weight $0.987$ against three one-parameter rivals: an exponential ($\Delta\mathrm{AICc}=+9.2$), a logistic ($+11.5$, degenerate) and a line ($+16.9$). The raw decline across the window is a factor $3.25$.

Two questions follow, and both are answered here in a data-independent way: \emph{why this shape}, and \emph{what survives division by the expected background}.

\subsection{Notation}
Throughout $b$ is an exponent and $A>0$ an amplitude, and
\[
T_{A,b}(x)=A(1+x)^{-b},\qquad x>-1,
\]
is the \emph{profile-form} family. All logarithms are natural. The residual analysis is normalised to the window $[0,1]$.

\section{Rigidity: the profile form is a law}

\begin{definition}[Scale composition]
For $x,y>-1$ put $x\star y=(1+x)(1+y)-1$.
\end{definition}

This is ordinary multiplication on $(0,\infty)$ transported through $x\mapsto 1+x$: it is associative and commutative with identity $0$, and is the natural composition when positions are measured relatively.

\begin{definition}[Scale multiplicativity]
A profile $T:(-1,\infty)\to\R$ is \emph{scale-multiplicative} if
\begin{equation}\label{eq:mult}
T(0)\,T(x\star y)=T(x)\,T(y)\qquad\text{for all }x,y>-1.
\end{equation}
\end{definition}

\begin{proposition}
Every $T_{A,b}$ is scale-multiplicative.
\end{proposition}

\begin{proof}
$1+(x\star y)=(1+x)(1+y)$ and $\bigl((1+x)(1+y)\bigr)^{-b}=(1+x)^{-b}(1+y)^{-b}$; multiply by $A^2$ and use $T_{A,b}(0)=A$.
\end{proof}

\begin{theorem}[Rigidity of the profile form]\label{thm:rigidity}
Let $T:(-1,\infty)\to\R$ be positive, continuous and scale-multiplicative. Then there is $b\in\R$ with
\[
T(x)=T(0)\,(1+x)^{-b}\qquad\text{for all }x>-1.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Put $A=T(0)>0$ and substitute $x=e^u-1$, a bijection $\R\to(-1,\infty)$ turning $\star$ into addition. Set $g(u)=\log\bigl(T(e^u-1)/A\bigr)$, well defined by positivity. Then \eqref{eq:mult} becomes Cauchy's equation $g(u+v)=g(u)+g(v)$, and $g$ is continuous, hence $\R$-linear: $g(u)=u\,g(1)$. For $x>-1$ take $u=\log(1+x)$ to get $T(x)=A\exp\bigl(g(1)\log(1+x)\bigr)=A(1+x)^{-b}$ with $b=-g(1)$.
\end{proof}

\begin{remark}
The three hypotheses are natural and all needed: positivity (a density), continuity (without it Hamel-basis pathologies reappear), and scale multiplicativity (relative offsets compose). Neither differentiability nor any growth condition is assumed.
\end{remark}

\begin{theorem}[Identifiability]
Let $A>0$. If $T_{A,b}=T_{A,b'}$ on $(-1,\infty)$ then $b=b'$.
\end{theorem}

\begin{proof}
Evaluate at $x=1$, cancel $A>0$, take logarithms and divide by $\log 2\neq 0$.
\end{proof}

\subsection{The window decline factor}

\begin{definition}
$\mathrm{DF}(b)=T_{A,b}(0)/T_{A,b}(2)=3^{b}$, independent of $A>0$.
\end{definition}

\begin{proposition}\label{prop:decline}
$\mathrm{DF}$ is strictly increasing, and $2.8<\mathrm{DF}(b)<4.1$ for every $b\in[0.991,1.218]$.
\end{proposition}

\begin{proof}[Proof sketch]
Use the rigorous enclosure $1.05<\log 3<1.14$, from $e^{1.05}<3<e^{1.14}$ via $e<2.7182818286$, $e^{y}\le(1-y)^{-1}$ for $y<1$, and $1+y\le e^{y}$. Then $\mathrm{DF}(b)=e^{b\log 3}$ lies between $e^{1.0406}>2.8$ and $e^{1.3886}<4.1$, the latter from $e^{0.3886}=(e^{0.048575})^{8}\le(1-0.048575)^{-8}<1.49$.
\end{proof}

The measured raw decline $3.25$ lies in this bracket, a consistency check the law supplies with no extra fitting.

\section{One invariant separates the winner from all three rivals}

\begin{definition}[Log-midpoint defect]
For $f>0$ put $D_f(t,h)=f(t-h)f(t+h)-f(t)^2$.
\end{definition}

\begin{theorem}[Strict log-convexity of the power law]\label{thm:logconv}
Let $A>0$, $b>0$, $h>0$ and $t-h>-1$. Then $T_{A,b}(t)^2<T_{A,b}(t-h)T_{A,b}(t+h)$.
\end{theorem}

\begin{proof}[Proof sketch]
$\bigl(1+(t-h)\bigr)\bigl(1+(t+h)\bigr)=(1+t)^2-h^2<(1+t)^2$, both positive; since $-b<0$, $s\mapsto s^{-b}$ is strictly decreasing, so the inequality reverses. Split both sides by multiplicativity of $s\mapsto s^{-b}$ and multiply by $A^2>0$.
\end{proof}

\begin{theorem}[Exponential family]
For $E_{C,k}(x)=Ce^{-kx}$, $D_{E_{C,k}}\equiv0$.
\end{theorem}

\begin{theorem}[Logistic family]
For $L_{C,k,x_0}(x)=C/\bigl(1+e^{k(x-x_0)}\bigr)$ with $C>0$, $D_{L}\le0$.
\end{theorem}

\begin{proof}[Proof sketch]
With $u=k(t-x_0)$ the claim is $(1+e^{u})^2\le(1+e^{u-kh})(1+e^{u+kh})$. The products of the exponentials agree exactly, and $e^{u-kh}+e^{u+kh}=e^{u}(e^{-kh}+e^{kh})\ge2e^{u}$ by AM--GM.
\end{proof}

\begin{theorem}[Affine family]
For $P_{p,q}(x)=p+qx$ one has the identity $D_{P_{p,q}}(t,h)=-q^2h^2\le0$, with no positivity hypothesis.
\end{theorem}

\begin{theorem}[Separation]\label{thm:sep}
Let $A>0$ and $b>0$. Then $T_{A,b}$ coincides on $(-1,\infty)$ with no exponential, no logistic profile with $C>0$, and no affine function.
\end{theorem}

\begin{proof}
At $t=h=1$, Theorem~\ref{thm:logconv} gives $T_{A,b}(0)T_{A,b}(2)>T_{A,b}(1)^2$, while every rival satisfies the reverse inequality at the same triple.
\end{proof}

\begin{remark}
Theorem~\ref{thm:sep} uses no data, no noise model and no criterion. The empirical comparison and this structural fact are independent lines of evidence pointing the same way.
\end{remark}

\section{What an Akaike weight can and cannot say}

\begin{definition}
For gaps $d_1,d_2,d_3$, $\displaystyle w(d_1,d_2,d_3)=\Bigl(1+e^{-d_1/2}+e^{-d_2/2}+e^{-d_3/2}\Bigr)^{-1}$.
\end{definition}

\begin{theorem}\label{thm:akaike}
For all real $d_1,d_2,d_3$:
\begin{enumerate}[label=(\roman*)]
\item $w\in(0,1)$;
\item $w$ is non-decreasing in each argument;
\item $w(0,d_2,d_3)<1/2$;
\item $w(d,d,d)\to1$ as $d\to\infty$;
\item if $d\le d_i$ for all $i$ then $w\ge\bigl(1+3e^{-d/2}\bigr)^{-1}$.
\end{enumerate}
\end{theorem}

Item (iii) is the point of substance: a tied rival caps the weight at $1/2$, so a weight near $1$ is genuine evidence and not an artefact of normalisation.

\begin{theorem}[The measured verdict]
$w(9.2,11.5,16.9)>0.98$.
\end{theorem}

\begin{proof}[Proof sketch]
From $e>2.7182818283$ one gets $e^{4}\ge54.59$. Hence $e^{4.6}=e^{4}e^{0.6}\ge54.59\cdot1.6\ge87$, so $e^{-4.6}\le0.0115$; $e^{5.75}\ge54.59\cdot2.75\ge150$, so $e^{-5.75}\le0.0067$; and $e^{8}=(e^{4})^2\ge2980$, so $e^{-8.45}\le0.00034$. The denominator is at most $1.01824$.
\end{proof}

\section{The exponent-one threshold and absorption of the decline}

\begin{definition}
The unit-amplitude \emph{window mass} is $W(b,X)=\int_0^X(1+x)^{-b}\,dx$, $X\ge0$.
\end{definition}

\begin{theorem}[Closed form and critical exponent]\label{thm:mass}
For $X\ge0$:
\begin{enumerate}[label=(\arabic*)]
\item if $b\neq1$, $W(b,X)=\dfrac{(1+X)^{1-b}-1}{1-b}$;
\item $W(1,X)=\log(1+X)$;
\item if $b>1$, $W(b,X)\to\dfrac{1}{b-1}$ as $X\to\infty$;
\item if $b\le1$, $W(b,X)\to\infty$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) and (2) are the fundamental theorem of calculus applied to the antiderivatives $(1+x)^{1-b}/(1-b)$ and $\log(1+x)$, the integrand being continuous on $[0,X]$. (3) $(1+X)^{1-b}\to0$ for $b>1$. (4) For $b=1$ use divergence of $\log$; for $b<1$, $(1+X)^{1-b}\to\infty$ with $1-b>0$ constant.
\end{proof}

\begin{corollary}[The measurement straddles the threshold]
Within $[0.991,1.218]$ there are exponents (e.g.\ $b=1$) with divergent total mass and exponents (e.g.\ $b=1.104$) with finite total mass.
\end{corollary}

The divergence is visible already in counts: by induction, using $\log\frac{n+2}{n+1}\le\frac{1}{n+1}$ (a case of $\log s\le s-1$),
\[
\log(n+1)\;\le\;\sum_{j=0}^{n-1}\frac{1}{j+1}.
\]

\subsection{The uniform scale-mixture background}

\begin{definition}
$\displaystyle M(x)=\int_0^1 e^{-xs}\,ds=\frac{1-e^{-x}}{x}$ for $x\neq0$: the uniform scale mixture of exponential regimes with rates in $[0,1]$.
\end{definition}

\begin{lemma}[Exponent-one squeeze]\label{lem:squeeze}
For $x\ge1$, $\dfrac{1}{2x}\le M(x)\le\dfrac1x$.
\end{lemma}

\begin{proof}
$0<e^{-x}\le e^{-1}\le1/2$ for $x\ge1$, so $1/2\le 1-e^{-x}<1$; divide by $x>0$.
\end{proof}

\begin{definition}
The \emph{residual} is $R_{A,b}(x)=T_{A,b}(x)/M(x)$.
\end{definition}

\begin{theorem}[Absorption bounds]\label{thm:absorb}
For $A>0$ and $x\ge1$,
\[
A\,x\,(1+x)^{-b}\;\le\;R_{A,b}(x)\;\le\;2A\,x\,(1+x)^{-b}.
\]
\end{theorem}

\begin{theorem}[The background eats the harmonic gradient]\label{thm:twothirds}
For every $A>0$ and $b\in\R$,
\[
\frac{R_{A,b}(1)}{R_{A,b}(3)}\;\le\;\frac{2}{3}\cdot\frac{T_{A,b}(1)}{T_{A,b}(3)}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:absorb}, $R_{A,b}(1)\le 2A2^{-b}$ and $R_{A,b}(3)\ge 3A4^{-b}>0$; divide.
\end{proof}

Empirically the background falls by $3.64$ where the profile falls by $3.25$: the mixture absorbs the entire raw decline and slightly over-absorbs it, which is why the beyond-background layer shows a shape rather than a slope.

\section{The beyond-background residual is peaked}

\begin{definition}
A function $f$ on $[0,1]$ is \emph{peaked} if it attains a maximum at an interior point and is neither monotone nor antitone on $[0,1]$.
\end{definition}

\begin{lemma}[Interior maximum from endpoint dominance]\label{lem:peak}
Let $f$ be continuous on $[0,1]$ and $c\in(0,1)$ with $f(0)<f(c)$ and $f(1)<f(c)$. Then $f$ attains its maximum at some $m\in(0,1)$, and is neither monotone nor antitone on $[0,1]$.
\end{lemma}

\begin{proof}
Compactness gives a maximiser $m$ with $f(c)\le f(m)$; $m\in\{0,1\}$ contradicts the strict inequalities. Monotonicity would force $f(c)\le f(1)$, antitonicity $f(c)\le f(0)$.
\end{proof}

Note that the hypothesis is a \emph{value} condition, which is what the data supply.

\subsection{The fitted residual}

With the measured end values $R(0)=0.80$, $R(1)=0.90$ and vertex $0.59$, the concave fit is
\begin{equation}\label{eq:Rhat}
\Rhat(x)=\frac45+\frac{59}{90}x-\frac59x^2 .
\end{equation}

\begin{proposition}[Exact concavity identity]
$\Rhat(0.59)-\Rhat(x)=\tfrac59(x-0.59)^2$ for all $x$; hence $0.59$ is the strict global maximiser and $\Rhat(0.59)=\tfrac{17881}{18000}\approx0.99339$.
\end{proposition}

\begin{corollary}
$\Rhat(0.59)\ge\tfrac65\Rhat(0)$, $\Rhat(0.59)\ge\tfrac{11}{10}\Rhat(1)$, and $\Rhat(0)<1$, $\Rhat(1)<1$.
\end{corollary}

So the apex clears the wall end by at least $20\%$ and the far end by at least $10\%$, while both ends are deficits; by Lemma~\ref{lem:peak} the residual is peaked.

\subsection{Robustness: the endpoint-pinned family}

\begin{definition}
For $c\in\R$ let $R_c(x)=\tfrac45+\bigl(\tfrac1{10}-c\bigr)x+cx^2$, so $R_c(0)=\tfrac45$ and $R_c(1)=\tfrac9{10}$; its apex is $x_c=\dfrac{1/10-c}{-2c}$ for $c\neq0$. The fit \eqref{eq:Rhat} is $R_{-5/9}$.
\end{definition}

\begin{theorem}[Sharp curvature threshold]\label{thm:threshold}
Let $c<0$.
\begin{enumerate}[label=(\arabic*)]
\item If $c<-1/10$ then $x_c\in(1/2,1)$ and $R_c$ is peaked on $[0,1]$.
\item If $-1/10\le c<0$ then $R_c$ is non-decreasing on $[0,1]$: no peak at all.
\item $x_{-1/10}=1$ exactly: at the threshold the apex sits on the right endpoint.
\item For every $c<0$, $R_c(x_c)\ge\tfrac{28}{25}R_c(0)$; and if $c\neq-1/10$ then $R_c(x_c)>9/10=R_c(1)$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
The identity $R_c(x_c)-R_c(x)=-c(x-x_c)^2$ gives a strict global maximum at $x_c$ for $c<0$. (1) $x_c>1/2$ always; $x_c<1\iff 1/10-c<-2c\iff c<-1/10$; then apply Lemma~\ref{lem:peak}. (2) $R_c(y)-R_c(x)=(y-x)\bigl[(1/10-c)+c(x+y)\bigr]$ and for $x,y\in[0,1]$ the bracket is $\ge 1/10+c\ge0$. (3) is computation. (4) $R_c(x_c)=\tfrac45-\tfrac{(1/10-c)^2}{4c}$, and $\tfrac{(1/10-c)^2}{4c}\le-0.096$ for all $c<0$ (tightest near $c=-0.092$), while $\tfrac{(1/10-c)^2}{4c}<-\tfrac1{10}\iff(c+1/10)^2>0$.
\end{proof}

\begin{theorem}[Invariance over the reported uncertainty]
Every $c\in[-0.62,-0.14]$ satisfies $c<-1/10$; hence $R_c$ is peaked throughout the reported curvature interval, with margin $0.04$ to the threshold.
\end{theorem}

\subsection{Layer separation}

\begin{lemma}
For $A>0$, $T_{A,b}$ is antitone on $[0,1]$ if $b\ge0$ and monotone if $b\le0$; in particular never peaked.
\end{lemma}

\begin{theorem}\label{thm:sepres}
For no $A>0$ and $b\in\R$ does $\Rhat$ coincide with $T_{A,b}$ on $[0,1]$.
\end{theorem}

\begin{theorem}[What the hump certifies]\label{thm:certify}
Let $A>0$, $c\in(0,1)$, and let $M^{\sharp}$ satisfy $M^{\sharp}(0)<M^{\sharp}(c)$ and $M^{\sharp}(1)<M^{\sharp}(c)$. Then $M^{\sharp}$ does not coincide with $T_{A,b}$ on $[0,1]$ for any $b$.
\end{theorem}

Applied to $M^{\sharp}=T/M$: an interior peak proves the background is \emph{not} a power-law rescaling of the profile --- and no more.

\section{Two corrections that sharpen the interpretation}

\begin{theorem}[A peak does not rule out a mixture background]\label{thm:twoatom}
Let $M_2(x)=\tfrac12e^{-x/20}+\tfrac12e^{-8x}$, a positive two-atom scale mixture with rates $1/20$ and $8$, and let $b=11/10$. Then $\rho=T_{1,b}/M_2$ satisfies $\rho(0)=1$, $\rho(0.3)>\tfrac54$, $\rho(1)<\tfrac54$, hence $\rho$ is peaked on $[0,1]$.
\end{theorem}

\begin{proof}[Proof sketch]
At $x=0.3$: $\log 1.3\le0.27$ (from $(1+27/800)^8\ge1.3$ and $1+y\le e^{y}$) gives $T_{1,b}(0.3)\ge e^{-0.297}\ge0.703$ via $e^{y}\le(1-y)^{-1}$, while $e^{-2.4}\le1/10$ (from $e^{2.4}\ge7.38\cdot1.4\ge10$) gives $M_2(0.3)\le0.55$. At $x=1$: $T_{1,b}(1)=2^{-1.1}<1/2$ and $M_2(1)\ge\tfrac12e^{-1/20}\ge19/40$. Apply Lemma~\ref{lem:peak}.
\end{proof}

\begin{theorem}[Peakedness is window-relative]\label{thm:window}
For $b=11/10$ let $\rho_U=T_{1,b}/M$. Then $\rho_U(3)\le0.69$, $\rho_U(10)\ge0.70$ and $\rho_U(100)\le0.69$; hence $\rho_U$ has an interior maximum on $[3,100]$ and is neither monotone nor antitone there.
\end{theorem}

\begin{proof}[Proof sketch]
Write $\rho_U(x)=(1+x)^{-11/10}x/(1-e^{-x})$ and convert rational exponents into exact integer comparisons: $11^{11}\le(100/7)^{10}$, $(229/50)^{10}\le4^{11}$, $146^{10}\le101^{11}$. Control the exponentials by $e^{3}\ge20$ and $e^{7}\ge1000$, then apply Lemma~\ref{lem:peak} on $[3,100]$.
\end{proof}

\begin{corollary}
An interior hump locates a feature \emph{of the analysed window}; by itself it is not evidence that the background is wrong. The defensible reading is Theorem~\ref{thm:certify} together with the localisation of the measured hump at $x\approx0.59$ inside $[0,1]$.
\end{corollary}

\section{The hump-location law and a critical exponent}

For $x>0$,
\begin{equation}\label{eq:factor}
\frac{T_{1,b}(x)}{M(x)}=\frac{\tau_b(x)}{1-e^{-x}},\qquad \tau_b(x)=x(1+x)^{-b},
\end{equation}
and $1-e^{-x}\to1$, so far from the origin the shape is governed by $\tau_b$.

\begin{theorem}[Hump-location law]\label{thm:hump}
For every $b>1$ the function $\tau_b$ has a unique maximiser on $[0,\infty)$, at
\[
x^\star=\frac{1}{b-1},
\]
being strictly increasing on $[0,x^\star]$ and strictly decreasing on $[x^\star,\infty)$. For $b\le1$, $\tau_b$ is strictly increasing on $[0,\infty)$ and has no maximiser.
\end{theorem}

\begin{proof}[Proof sketch]
$\tau_b'(x)=(1+x)^{-b-1}\bigl(1-(b-1)x\bigr)$ for $x>-1$; the first factor is positive, and the second changes sign exactly at $1/(b-1)$ when $b>1$, and is positive throughout $x\ge0$ when $b\le1$.
\end{proof}

\begin{corollary}
At $b=11/10$, $x^\star=10$ --- exactly where the hump of Theorem~\ref{thm:window} sits.
\end{corollary}

\begin{remark}
Theorem~\ref{thm:hump} is a dichotomy at the same threshold $b=1$ as Theorem~\ref{thm:mass}: below it no maximiser exists, above it the maximiser sits at $1/(b-1)$ and recedes to infinity as $b\downarrow1$. The reported interval $[0.991,1.218]$ straddles this too.
\end{remark}

\begin{theorem}[Confinement]\label{thm:confine}
Let $b>1$ and $0<x_0\le x$. If $\tau_b(x)<\bigl(1-e^{-x_0}\bigr)\tau_b(x^\star)$, then
\[
\frac{T_{1,b}(x)}{M(x)}<\frac{T_{1,b}(x^\star)}{M(x^\star)}.
\]
Moreover, for every $b>1$ and $x_0>0$ this hypothesis holds for all sufficiently large $x$, since $\tau_b(x)\le(1+x)^{1-b}\to0$.
\end{theorem}

\begin{proof}[Proof sketch]
From \eqref{eq:factor} and $1-e^{-x_0}\le 1-e^{-x}<1$ we get $\tau_b(x)\le T_{1,b}(x)/M(x)\le \tau_b(x)/(1-e^{-x_0})$ for $x\ge x_0>0$; chain the upper bound at $x$, the hypothesis, and the lower bound at $x^\star$.
\end{proof}

\subsection{A critical exponent}

For $x>0$,
\begin{equation}\label{eq:logder}
\frac{d}{dx}\log\frac{T_{1,b}(x)}{M(x)}=\frac1x-\frac{b}{1+x}-\frac{1}{e^{x}-1},
\end{equation}
a competition between the algebraic part, positive up to $x^\star=1/(b-1)$, and an exponential correction that is large near the origin.

\begin{lemma}[Pad\'e bound]\label{lem:pade}
For $0<x<2$, $e^{x}<\dfrac{2+x}{2-x}$.
\end{lemma}

\begin{proof}[Proof sketch]
$h(t)=(2+t)e^{-t}-(2-t)$ has $h(0)=0$ and $h'(t)=1-(1+t)e^{-t}>0$ for $t>0$ since $1+t<e^{t}$; hence $h(x)>0$.
\end{proof}

\begin{lemma}\label{lem:corr}
For every $x>0$, $\dfrac1x-\dfrac12<\dfrac{1}{e^{x}-1}$.
\end{lemma}

\begin{proof}
For $x\ge2$ the left side is $\le0$. For $0<x<2$, Lemma~\ref{lem:pade} gives $e^{x}-1<\frac{2x}{2-x}$; inverting, $\frac{1}{e^{x}-1}>\frac{2-x}{2x}=\frac1x-\frac12$.
\end{proof}

\begin{theorem}[No hump for large exponents]\label{thm:nohump}
For every $b\ge3/2$ the residual $x\mapsto T_{1,b}(x)/M(x)$ is strictly decreasing on $(0,\infty)$.
\end{theorem}

\begin{proof}[Proof sketch]
It suffices that \eqref{eq:logder} be negative for all $x>0$. For $0<x\le2$: by Lemma~\ref{lem:corr} it suffices that $b/(1+x)\ge1/2$, i.e.\ $x\le2b-1$, true since $2b-1\ge2$. For $x>2$: $1/x\le b/(1+x)$ because $1+x\le bx$ holds for $x>2\ge1/(b-1)$, and the correction is strictly negative. Strict antitonicity of the logarithm transfers to the positive residual.
\end{proof}

\begin{theorem}[Bracketing the humping regime]
The uniform-mixture residual humps at $b=11/10$ (Theorem~\ref{thm:window}) and is strictly monotone for every $b\ge3/2$ (Theorem~\ref{thm:nohump}); hence a critical exponent $b_c\in(11/10,3/2)$ separates the two regimes. Numerically $b_c\approx1.1605$.
\end{theorem}

\begin{corollary}
The hump is not a structural property of the profile/background pair: the same pair is humped at one exponent and monotone at another. Since $[0.991,1.218]$ contains exponents on both sides of $b_c$, the experiment does not settle whether the pair humps outside the measured window.
\end{corollary}

\begin{remark}
The constant $3/2$ is exactly what the two elementary bounds give: the argument needs $1/(b-1)\le2\le2b-1$, i.e.\ $2b^2-3b\ge0$. Closing the gap to $b_c\approx1.1605$ requires a sharper approximation to $1/(e^{x}-1)$ near $x\approx1$.
\end{remark}

\section{Algorithms}

\paragraph{Endpoint-pinned curvature fit.}
Writing $R_c(x)=\tfrac45+\tfrac{x}{10}+c(x^2-x)$, least squares over the single free parameter gives
\[
\hat c=\frac{\sum_i\bigl(r_i-\tfrac45-\tfrac{x_i}{10}\bigr)(x_i^2-x_i)}{\sum_i (x_i^2-x_i)^2},
\]
at cost $O(n)$; the apex is $x_{\hat c}=(1/10-\hat c)/(-2\hat c)$ and the peak verdict is the single test $\hat c<-1/10$.

\paragraph{Cluster bootstrap.}
Hits are clustered by source semiprime, so resampling is at the cluster level: for each of $B$ replicates, draw $128$ semiprimes with replacement, pool their hits, refit the exponent, and report the empirical $2.5\%/97.5\%$ quantiles. Cost $O(Bn)$; the reported interval $[0.991,1.218]$ came from $B=2000$.

\paragraph{Model comparison.}
Fit each family, compute $\mathrm{AICc}=n\log(\mathrm{RSS}/n)+2k+\frac{2k(k+1)}{n-k-1}$, form the gaps against the best model, and evaluate the weight. Theorem~\ref{thm:akaike}(iii) is the interpretive guard-rail.

\section{Discussion}

Three facts are established with no reference to the data: the profile form is forced by scale multiplicativity with an identifiable exponent (Theorem~\ref{thm:rigidity}); a single convexity invariant separates it from all three rival families (Theorem~\ref{thm:sep}); and the mixture background removes at least a third of the raw decline for every amplitude and exponent (Theorem~\ref{thm:twothirds}).

With the data, the interior hump is robust: it holds for every endpoint-pinned curvature below the sharp threshold $-1/10$, and the reported interval $[-0.62,-0.14]$ lies entirely below it. Its consequence is exactly Theorem~\ref{thm:certify}.

Two over-readings were refuted: an interior peak does not rule out mixture backgrounds (Theorem~\ref{thm:twoatom}), and peakedness is window-relative (Theorem~\ref{thm:window}). An earlier claim that $T/M$ can never have an interior maximum is false and was withdrawn; Theorems~\ref{thm:hump} and~\ref{thm:nohump} give the correct picture.

Finally, the measured exponent interval $[0.991,1.218]$ straddles two distinct qualitative thresholds: $b=1$, separating divergent from finite total window mass and non-existence from existence of a maximiser of $\tau_b$; and $b_c\approx1.1605$, separating humped from monotone residuals. This converts ``estimate $b$'' into the sharper experimental requirement ``separate $b$ from $1$ and from $\approx1.16$''.

\section{Future work}

\begin{enumerate}[label=(\arabic*)]
\item Determine $b_c$ exactly, or bracket it inside $(1.15,1.17)$, by replacing Lemma~\ref{lem:pade} with a two-sided rational approximation to $1/(e^{x}-1)$ near $x\approx1$; the defining condition is a double root of $\frac1x-\frac{b}{1+x}=\frac{1}{e^{x}-1}$.
\item Characterise which positive scale mixtures $M(x)=\int e^{-sx}d\mu(s)$ admit a humped residual against a fixed power law, in terms of the spread of $\log s$ under $\mu$.
\item Sharpen absorption: replace the squeeze of Lemma~\ref{lem:squeeze} by $M(x)=1/x-e^{-x}/x$ to turn the constant $2/3$ of Theorem~\ref{thm:twothirds} into an $x$-dependent bound tending to $1$.
\item Quantify the discrete-to-continuum error between $\sum_{j<n}(1+x_j)^{-b}$ and $\int_0^{X}(1+x)^{-b}dx$ on the actual sampling grid, so the critical-exponent dichotomy can be tested on counts.
\item Develop the two-coordinate analogue of scale multiplicativity and its rigidity theorem, to test whether the observed layer separation persists.
\end{enumerate}

